            arabicText = "يس ۝ وَالْقُرْآنِ الْحَكِيمِ ۝ إِنَّكَ لَمِنَ الْمُرْسَلِينَ ۝ عَلَىٰ صِرَاطٍ مُّسْتَقِيمٍ ۝ تَنزِيلَ الْعَزِيزِ الرَّحِيمِ ۝ لِتُنذِرَ قَوْمًا مَّا أُنذِرَ آبَاؤُهُمْ فَهُمْ غَافِلُونَ ۝ لَقَدْ حَقَّ الْقَوْلُ عَلَىٰ أَكْثَرِهِمْ فَهُمْ لَا يُؤْمِنُونَ ۝",
            transliterationBangla = "১. ইয়া-সীন।\n২. ওয়াল কুরআনিল হাকীম।\n৩. ইন্নাকা লামিনাল মুরসালীন।\n৪. 'আলা সিরাতিম মুসতাক্বীম।\n৫. তানযীলাল 'আযীযির রাহীম।\n৬. লিতুনযিরা কাওমাম মা উনযিরা আবা-উহুম ফাহুম গাফিলূন।\n৭. লাক্বাদ হাক্বক্বল ক্বাওলু 'আলা আকছারিহিম ফাহুম লা ইউ'মিনূন।",
            translationBangla = "১. ইয়া-সীন।\n২. বিজ্ঞানময় কুরআনের শপথ!\n৩. নিশ্চয় আপনি রাসূলদের অন্তর্ভুক্ত,\n৪. সরল-সঠিক পথের ওপর প্রতিষ্ঠিত।\n৫. এই কুরআন মহা পরাক্রমশালী পরম দয়ালু আল্লাহর অবতারণ,\n৬. যাতে আপনি এমন জাতিকে সতর্ক করেন যাদের পূর্বপুরুষদের সতর্ক করা হয়নি, ফলে তারা উদাসীন।\n৭. অবশ্যই তাদের অধিকাংশের বিরুদ্ধে চূড়ান্ত বাণী সাব্যস্ত হয়েছে, সুতরাং তারা ঈমান আনবে না।",
            virtuesBangla = "কুরআনের হৃৎপিণ্ড বা কালব। এটি পাঠে মহান আল্লাহ জীবনের গোনাহসমূহ ক্ষমা করেন।"),
