            arabicText = "الرَّحْمَٰنُ ۝ عَلَّمَ الْقُرْآنَ ۝ خَلَقَ الْإِنسَانَ ۝ عَلَّمَهُ الْبَيَانَ ۝ الشَّمْسُ وَالْقَمَرُ بِحُسْبَانٍ ۝ وَالنَّجْمُ وَالشَّجَرُ يَسْجُدَانِ ۝ وَالسَّمَاءَ رَفَعَهَا وَوَضَعَ الْمِيزَانَ ۝ أَلَّا تَطْغَوْا فِي الْمِيزَانِ ۝ وَأَقِيمُوا الْوَزْنَ بِالْقِسْطِ وَلَا تُخْسِرُوا الْمِيزَانَ ۝ فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ ۝",
            transliterationBangla = "১. আর-রাহমান।\n২. 'আল্লামাল কুরআন।\n৩. খালাক্বাল ইনসান।\n৪. 'আল্লামাহুল বায়ান।\n৫. আশ-শামসু ওয়াল ক্বামারু বিহুসবান।\n৬. ওয়ান নাজমু ওয়াশ শাজারু ইয়াসজুদান।\n৭. ওয়াস সামা-আ রাফা'আহা ওয়া ওয়াদা'আল মীযান।\n৮. আল্লা তাতগাও ফিল মীযান।\n৯. ওয়া আক্বীমুল ওয়াযনা বিলক্বিসতি ওয়ালা তুখসিরুল মীযান।\n১০. ফাবি-আইয়্যি আ-লা-ই রাব্বিকুমা তুকায়্যিবান।",
            translationBangla = "১. পরম দয়ালু আল্লাহ,\n২. তিনি শিক্ষা দিয়েছেন কুরআন,\n৩. সৃষ্টি করেছেন মানুষ,\n৪. তাকে শিখিয়েছেন ভাব প্রকাশ ও ভাষা।\n৫. সূর্য ও চন্দ্র আবর্তন করে নির্ধারিত হিসেবে,\n৬. আর লতাগুল্ম ও বৃক্ষরাজি সিজদা করে,\n৭. আকাশকে তিনি সমুন্নত করেছেন এবং স্থাপন করেছেন ভারসাম্য,\n৮. যাতে তোমরা পরিমাপে ভারসাম্য লঙ্ঘন না করো,\n৯. এবং ন্যায়সঙ্গত ওজন কায়েম করো এবং ওজনে কম দিয়ো না।\n১০. অতএব তোমরা তোমাদের রবের কোন কোন নিয়ামতকে অস্বীকার করবে?",
            virtuesBangla = "উরূসুল কুরআন বা কুরআনের বধূ/সৌন্দর্য। এতে ৩১ বার 'অতএব তোমরা তোমাদের রবের কোন কোন নিয়ামতকে অস্বীকার করবে' পুনরাবৃত্ত হয়েছে।"),
        QuranSurah(56, "الواقعة", "আল-ওয়াকিয়াহ", "Al-Waqi'ah", "নিশ্চিত মহাপ্রলয়", 96, "মাক্কী", "পারা ২৭",
