            juzNumber = "পারা ২৮",
            arabicText = "يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نُودِيَ لِلصَّلَاةِ مِن يَوْمِ الْجُمُعَةِ فَاسْعَوْا إِلَىٰ ذِكْرِ اللَّهِ وَذَرُوا الْبَيْعَ ۚ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ ۝ فَإِذَا قُضِيَتِ الصَّلَاةُ فَانتَشِرُوا فِي الْأَرْضِ وَابْتَغُوا مِن فَضْلِ اللَّهِ وَاذْكُرُوا اللَّهَ كَثِيرًا لَّعَلَّكُمْ تُفْلِحُونَ ۝",
            transliterationBangla = "৯. ইয়া-আইয়্যুহাল্লাযীনা আমানূ ইযা নূদিয়া লিস-সালাতি মিঁই ইয়াওমিল জুমু'আতি ফাস'আও ইলা যিকরিল্লাহি ওয়া যারুল বাই', যালিকুম খাইরুল লাকুম ইন কুনতুম তা'লামূন।\n১০. ফাইযা ক্বুদিয়াতিস সালাতু ফানতাশিরূ ফিল আরদ্বি ওয়াবতাগূ মিন ফাদ্বলিল্লাহি ওয়াযকুরুল্লাহা কাছীরাল লা'আল্লাকুম তুফলিহূন।",
            translationBangla = "৯. হে মুমিনগণ! যখন জুমার দিনে সালাতের জন্য আহবান জানানো হয়, তখন তোমরা আল্লাহর স্মরণের দিকে দ্রুত ছুটে যাও এবং ক্রয়-বিক্রয় বন্ধ রাখো; এটিই তোমাদের জন্য পরম কল্যাণকর, যদি তোমরা জানতে!\n১০. অতঃপর যখন সালাত সমাপ্ত হবে, তখন তোমরা জমিনে ছড়িয়ে পড়ো এবং আল্লাহর অনুগ্রহ (জীবিকা) অন্বেষণ করো এবং আল্লাহকে বেশি বেশি স্মরণ করো, যাতে তোমরা সফলকাম হও।",
            virtuesBangla = "জুমার আজানের সাথে সাথে দুনিয়াবী কাজ ছেড়ে মসজিদে যাওয়ার পবিত্র নির্দেশ সংবলিত সূরা।"
