        QuranSurah(67, "الملك", "আল-মুলক", "Al-Mulk", "সার্বভৌম কর্তৃত্ব", 30, "মাক্কী", "পারা ২৯",
            arabicText = "تَبَارَكَ الَّذِي بِيَدِهِ الْمُلْكُ وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ ۝ الَّذِي خَلَقَ الْمَوْتَ وَالْحَيَاةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا ۚ وَهُوَ الْعَزِيزُ الْغَفُورُ ۝ الَّذِي خَلَقَ سَبْعَ سَمَاوَاتٍ طِبَاقًا ۖ مَّا تَرَىٰ فِي خَلْقِ الرَّحْمَٰنِ مِن تَفَاوُتٍ ۖ فَارْجِعِ الْبَصَرَ هَلْ تَرَىٰ مِن فُطُورٍ ۝",
            transliterationBangla = "১. তাবারাকাল্লাযী বিয়াদিহিল মুলকু ওয়াহুওয়া 'আলা কুল্লি শাইয়িন ক্বাদীর।\n২. আল্লাযী খালাক্বাল মাওতা ওয়াল হায়াতা লিয়াবলুওয়াকুম আইয়্যুকুম আহসানু 'আমালা, ওয়াহুওয়াল 'আযীযুল গাফূর।\n৩. আল্লাযী খালাক্বা সাব'আ সামাওয়াতিম তিবা-ক্বা, মা তারা ফী খালক্বির রাহমানি মিন তাফাউত, ফারজি'ইল বাসারা হাল তারা মিন ফুতূর।",
            translationBangla = "১. বরকতময় তিনি, যাঁর হাতে সমস্ত রাজত্ব এবং তিনি সবকিছুর ওপর সর্বশক্তিমান।\n২. যিনি সৃষ্টি করেছেন মৃত্যু ও জীবন, তোমাদেরকে পরীক্ষা করার জন্য যে কে কর্মে তোমাদের মধ্যে উত্তম; এবং তিনি পরাক্রমশালী, ক্ষমাশীল।\n৩. যিনি সৃষ্টি করেছেন সপ্ত আসমান স্তরে স্তরে; পরম করুণাময়ের সৃষ্টিতে আপনি কোনো অসংগতি দেখতে পাবেন না; পুনরায় দৃষ্টি ফেরান, কোনো ফাটল দেখতে পান কি?",
            virtuesBangla = "সূরা আল-মুলক কবরের আজাব থেকে মুক্তিদানকারী সূরা। নবীজি (সাঃ) রাতে ঘুমানোর পূর্বে এ সূরা তিলাওয়াত করতেন।"),
