        QuranSurah(91, "الشمس", "আশ-শামস", "Ash-Shams", "সূর্য", 15, "মাক্কী", "পারা ৩০"),
        QuranSurah(92, "الليل", "আল-লাইল", "Al-Layl", "রাত্রি", 21, "মাক্কী", "পারা ৩০"),
        QuranSurah(93, "الضحى", "আদ-দুহা", "Ad-Duha", "পূর্বাহ্ণ বা দ্বিপ্রহর", 11, "মাক্কী", "পারা ৩০",
            arabicText = "وَالضُّحَىٰ ۝ وَاللَّيْلِ إِذَا سَجَىٰ ۝ مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ ۝ وَلَلْآخِرَةُ خَيْرٌ لَّكَ مِنَ الْأُولَىٰ ۝ وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰ ۝ أَلَمْ يَجِدْكَ يَتِيمًا فَآوَىٰ ۝ وَوَجَدَكَ ضَالًّا فَهَدَىٰ ۝ وَوَجَدَكَ عَائِلًا فَأَغْنَىٰ ۝ فَأَمَّا الْيَتِيمَ فَلَا تَقْهَرْ ۝ وَأَمَّا السَّائِلَ فَلَا تَنْهَرْ ۝ وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ ۝",
            transliterationBangla = "১. ওয়াদ দুহা।\n২. ওয়াল্লাইলি ইযা সাজা।\n৩. মা ওয়াদ্দা'আকা রাব্বুকা ওয়া মা ক্বলা।\n৪. ওয়ালাল আখিরাতু খাইরুল লাকা মিনাল ঊলা।\n৫. ওয়া লাসাওফা ইউ'ত্বীকা রাব্বুকা ফাতারদ্বা।\n৬. আলাম ইয়াজিদকা ইয়াতীমান ফাআওয়া।\n৭. ওয়া ওয়াজাদাকা দ্বাল্লান ফাহাদা।\n৮. ওয়া ওয়াজাদাকা 'আ-ইলান ফাআগনা।\n৯. ফা আম্মাল ইয়াতীমা ফালা তাক্বহার।\n১০. ওয়া আম্মাস সা-ইলা ফালা তানহার।\n১১. ওয়া আম্মা বিনি'মাতি রাব্বিকা ফাহাদ্দিছ।",
            translationBangla = "১. শপথ পূর্বাহ্ণের উজ্জ্বল রৌদ্রের!\n২. এবং শপথ রাত্রির যখন তা নিঝুম হয়!\n৩. আপনার প্রতিপালক আপনাকে ত্যাগ করেননি এবং অসন্তুষ্টও হননি।\n৪. আপনার জন্য পরকাল অবশ্যই ইহকালের চেয়ে শ্রেয়।\n৫. অচিরেই আপনার রব আপনাকে এতো দান করবেন যে আপনি সন্তুষ্ট হয়ে যাবেন।\n৬. তিনি কি আপনাকে পিতৃহীন অবস্থায় পাননি, অতঃপর আশ্রয় দেননি?\n৭. তিনি আপনাকে পেয়েছিলেন অন্বেষণরত অবস্থায়, অতঃপর পথ দেখিয়েছেন।\n৮. এবং তিনি আপনাকে পেয়েছিলেন নিঃস্ব অবস্থায়, অতঃপর অভাবমুক্ত করেছেন।\n৯. অতএব আপনি এতিমের প্রতি কঠোর হবেন না,\n১০. এবং সাহায্যপ্রার্থীকে ধমক দেবেন না,\n১১. আর আপনার প্রতিপালকের নিয়ামতসমূহ প্রকাশ করুন ও বর্ণনা করুন।"),
        QuranSurah(94, "الشرح", "আশ-শারহ / আল-ইনশিরাহ", "Ash-Sharh", "বক্ষ প্রশস্তকরণ", 8, "মাক্কী", "পারা ৩০",
            arabicText = "أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ ۝ وَوَضَعْنَا عَنكَ وِزْرَكَ ۝ الَّذِي أَنقَضَ ظَهْرَكَ ۝ وَرَفَعْنَا لَكَ ذِكْرَكَ ۝ فَإِنَّ مَعَ الْعُسْرِ يُسْرًا ۝ إِنَّ مَعَ الْعُسْرِ يُسْرًا ۝ فَإِذَا فَرَغْتَ فَانصَبْ ۝ وَإِلَىٰ رَبِّكَ فَارْغَب ۝",
            transliterationBangla = "১. আলাম নাশরাহ লাকা সাদরাক।\n২. ওয়া ওয়াদা'না 'আনকা বিযরাক।\n৩. আল্লাযী-আনক্বাদা জাহরাক।\n৪. ওয়া রাফা'না লাকা যিকরাক।\n৫. ফাইন্না মা'আল 'উসরি ইউসরা।\n৬. ইন্না মা'আল 'উসরি ইউসরা।\n৭. ফায়িযা ফারাগতা ফানসাব।\n৮. ওয়া ইলা রাব্বিকা ফারগাব।",
            translationBangla = "১. আমি কি আপনার বক্ষ আপনার কল্যাণে প্রশস্ত করে দিইনি?\n২. এবং আমি আপনার ওপর থেকে অপসারিত করেছি আপনার গুরুভার,\n৩. যা আপনার পিঠ নুয়ে দিচ্ছিল।\n৪. এবং আপনার সম্মানকে করেছি সমুচ্চ।\n৫. নিশ্চয়ই কষ্টের সাথেই রয়েছে স্বস্তি!\n৬. নিঃসন্দেহে কষ্টের সাথেই রয়েছে স্বস্তি!\n৭. অতএব যখনই অবসর পান, ইবাদতে নিমগ্ন হোন,\n৮. এবং একমাত্র আপনার রবের প্রতি মনোনিবেশ করুন।"),
        QuranSurah(95, "التين", "আত-তীন", "At-Tin", "ডুমুর বা আঞ্জীর", 8, "মাক্কী", "পারা ৩০",
            arabicText = "وَالتِّينِ وَالزَّيْتُونِ ۝ وَطُورِ سِينِينَ ۝ وَهَٰذَا الْبَلَدِ الْأَمِينِ ۝ لَقَدْ خَلَقْنَا الْإِنسَانَ فِي أَحْسَنِ تَقْوِيمٍ ۝ ثُمَّ رَدَدْنَاهُ أَسْفَلَ سَافِلِينَ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ ۝ فَمَا يُكَذِّبُكَ بَعْدُ بِالدِّينِ ۝ أَلَيْسَ اللَّهُ بِأَحْكَمِ الْحَاكِمِينَ ۝",
            transliterationBangla = "১. ওয়াত তীনী ওয়ায যাইতূন।\n২. ওয়া তূরি সীনীন।\n৩. ওয়া হাযাল বালাদিল আমীন।\n৪. লাক্বাদ খালাক্বনাল ইনসানা ফী আহসানি তাক্ববীম।\n৫. ছুম্মা রাদাদনাহু আসফালা সাফিলীন।\n৬. ইল্লাল্লাযীনা আমানূ ওয়া 'আমিলুস সালিহাতি ফালাহুম আজরুন গাইরু মামনূন।\n৭. ফামা ইউকাযযিবুকা বা'দু বিদ্দীন।\n৮. আলাইসাল্লাহু বিআহকামিল হাকিমীন।",
            translationBangla = "১. শপথ আঞ্জীর (ডুমুর) ও জলপাইয়ের,\n২. এবং সীনাই পর্বতের,\n৩. এবং এই নিরাপদ নগরীর (মক্কা মুকাররমার)।\n৪. নিশ্চয়ই আমি মানুষকে সৃষ্টি করেছি সর্বোত্তম সুন্দর গঠনে।\n৫. অতঃপর আমি তাকে নামিয়ে দিয়েছি সর্বনিম্নের নিম্নতম স্তরে।\n৬. তবে তারা ব্যতীত যারা ঈমান এনেছে ও সৎকাজ করেছে; তাদের জন্য রয়েছে নিরবচ্ছিন্ন মহাপুরস্কার।\n৭. অতএব এরপর কিসে তোমাকে শেষ বিচার অস্বীকার করতে প্ররোচিত করে?\n৮. আল্লাহ কি বিচারকদের মধ্যে সর্বশ্রেষ্ঠ বিচারক নন?"),
        QuranSurah(96, "العلق", "আল-আলাক", "Al-'Alaq", "রক্তপিণ্ড", 19, "মাক্কী", "পারা ৩০",
            arabicText = "اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ ۝ خَلَقَ الْإِنسَانَ مِنْ عَلَقٍ ۝ اقْرَأْ وَرَبُّكَ الْأَكْرَمُ ۝ الَّذِي عَلَّمَ بِالْقَلَمِ ۝ عَلَّمَ الْإِنسَانَ مَا لَمْ يَعْلَمْ ۝",
            transliterationBangla = "১. ইক্বরা বিসমি রাব্বিকাল্লাযী খালাক্ব।\n২. খালাক্বাল ইনসানা মিন 'আলাক্ব।\n৩. ইক্বরা ওয়া রাব্বুকাল আকরাম।\n৪. আল্লাযী 'আল্লামা বিল ক্বালাম।\n৫. 'আল্লামাল ইনসানা মা লাম ইয়া'লাম।",
            translationBangla = "১. পাঠ করুন আপনার প্রতিপালকের নামে যিনি সৃষ্টি করেছেন,\n২. সৃষ্টি করেছেন মানুষকে রক্তপিণ্ড থেকে।\n৩. পাঠ করুন, আর আপনার প্রতিপালক পরম সম্মানিত,\n৪. যিনি কলমের সাহায্যে শিক্ষা দিয়েছেন,\n৫. মানুষকে শিখিয়েছেন যা সে জানত না।",
            virtuesBangla = "পবিত্র কুরআনের সর্বপ্রথম অবতীর্ণ ওহী (হেরা গুহায় প্রথম ৫ আয়াত)।"),
        QuranSurah(97, "القدر", "আল-ক্বদর", "Al-Qadr", "মহিমান্বিত ভাগ্যরজনী", 5, "মাক্কী", "পারা ৩০",
            arabicText = "إِنَّا أَنزَلْنَاهُ فِي لَيْلَةِ الْقَدْرِ ۝ وَمَا أَدْرَاكَ مَا لَيْلَةُ الْقَدْرِ ۝ لَيْلَةُ الْقَدْرِ خَيْرٌ مِّنْ أَلْفِ شَهْرٍ ۝ تَنَزَّلُ الْمَلَائِكَةُ وَالرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرٍ ۝ سَلَامٌ هِيَ حَتَّىٰ مَطْلَعِ الْفَجْرِ ۝",
            transliterationBangla = "১. ইন্না-আনযালনাহু ফী লাইলাতিল ক্বদর।\n২. ওয়া মা-আদরাকা মা লাইলাতুল ক্বদর।\n৩. লাইলাতুল ক্বদরি খাইরুম মিন আলফি শাহর।\n৪. তানায্যালুল মালাইকাতু ওয়ার রূহু ফীহা বিইযনি রাব্বিহিম মিন কুল্লি আমর।\n৫. সালামুন হিয়া হাত্তা মাতলা'ইল ফাজর।",
            translationBangla = "১. নিশ্চয়ই আমি এই কুরআন অবতীর্ণ করেছি মহিমান্বিত ক্বদরের রাতে।\n২. আর আপনি কি জানেন মহিমান্বিত ক্বদরের রজনী কী?\n৩. ক্বদরের রাত হাজার মাসের চেয়েও শ্রেষ্ঠ।\n৪. এতে ফেরেশতাগণ এবং রূহ (জিবরাঈল আঃ) তাঁদের প্রতিপালকের অনুমতিক্রমে প্রত্যেক নির্দেশ নিয়ে অবতীর্ণ হন।\n৫. শান্তিময় এই রজনী, যা ফজর উদয় পর্যন্ত অব্যাহত থাকে।"),
        QuranSurah(98, "البينة", "আল-বায়্যিনাহ", "Al-Bayyinah", "সুস্পষ্ট প্রমাণ", 8, "মাদানী", "পারা ৩০"),
        QuranSurah(99, "الزلزلة", "আজ-যালযালাহ / আল-যিলযাল", "Az-Zalzalah", "মহাকম্পন", 8, "মাদানী", "পারা ৩০",
            arabicText = "إِذَا زُلْزِلَتِ الْأَرْضُ زِلْزَالَهَا ۝ وَأَخْرَجَتِ الْأَرْضُ أَثْقَالَهَا ۝ وَقَالَ الْإِنسَانُ مَا لَهَا ۝ يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا ۝ بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا ۝ يَوْمَئِذٍ يَصْدُرُ النَّاسُ أَشْتَاتًا لِّيُرَوْا أَعْمَالَهُمْ ۝ فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ ۝ وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ ۝",
            transliterationBangla = "১. ইযা যুলযিলাতিল আরদু যিলযালাহা।\n২. ওয়া আখরাজাতিল আরদু আসক্বালাহা।\n৩. ওয়া ক্বলাল ইনসানু মা লাহা।\n৪. ইয়াওমাইযিন তুহাদ্দিছু আখবারাহা।\n৫. বিআন্না রাব্বাকা আওহা লাহা।\n৬. ইয়াওমাইযিঁই ইয়াসদুরুন্নাসু আশতাতাল লিইউরাও আ'মালাহুম।\n৭. ফামাইঁ ইয়া'মাল মিছক্বলা যাররাতিন খাইরাইঁ ইয়ারাহ।\n৮. ওয়া মাইঁ ইয়া'মাল মিছক্বলা যাররাতিন শাররাইঁ ইয়ারাহ।",
            translationBangla = "১. যখন পৃথিবী তার ভয়াবহ কম্পনে প্রকম্পিত হবে,\n২. এবং পৃথিবী তার ভেতরের ভারসমূহ বের করে দেবে,\n৩. আর মানুষ বলবে: এর কী হলো?\n৪. সেদিন পৃথিবী তার সকল বৃত্তান্ত প্রকাশ করবে,\n৫. কারণ আপনার রব তাকে নির্দেশ দেবেন।\n৬. সেদিন মানুষ বিভিন্ন দলে বের হবে যাতে তাদের আমলসমূহ দেখানো যায়।\n৭. অতএব কেউ অণু পরিমাণ সৎকাজ করলে সে তা দেখতে পাবে,\n৮. আর কেউ অণু পরিমাণ অসৎকাজ করলেও তা দেখতে পাবে।"),
        QuranSurah(100, "العاديات", "আল-আদিয়াত", "Al-'Adiyat", "অভিযানকারী অশ্বদল", 11, "মাক্কী", "পারা ৩০"),
        QuranSurah(101, "القارعة", "আল-ক্বারিয়া", "Al-Qari'ah", "মহাপ্রলয়", 11, "মাক্কী", "পারা ৩০",
            arabicText = "الْقَارِعَةُ ۝ مَا الْقَارِعَةُ ۝ وَمَا أَدْرَاكَ مَا الْقَارِعَةُ ۝ يَوْمَ يَكُونُ النَّاسُ كَالْفَرَاشِ الْمَبْثُوثِ ۝ وَتَكُونُ الْجِبَالُ كَالْعِهْنِ الْمَنفُوشِ ۝ فَأَمَّا مَن ثَقُلَتْ مَوَازِينُهُ ۝ فَهُوَ فِي عِيشَةٍ رَّاضِيَةٍ ۝ وَأَمَّا مَنْ خَفَّتْ مَوَازِينُهُ ۝ فَأُمُّهُ هَاوِيَةٌ ۝ وَمَا أَدْرَاكَ مَا هِيَهْ ۝ نَارٌ حَامِيَةٌ ۝",
            transliterationBangla = "১. আল-ক্বারি'আহ।\n২. মাল ক্বারি'আহ।\n৩. ওয়া মা আদরাকা মাল ক্বারি'আহ।\n৪. ইয়াওমা ইয়াকূনুন নাসু কাল ফার্যাশিল মাবছূছ।\n৫. ওয়া তাকূনুল জিবালু কাল 'ইহনিল মানফূশ।\n৬. ফা আম্মা মান সাকুলাত মাওয়াযীনুহ।\n৭. ফাহুওয়া ফী 'ঈশাতির রাদ্বিয়াহ।\n৮. ওয়া আম্মা মান খাফফাত মাওয়াযীনুহ।\n৯. ফা উম্মুহূ হাবিয়াহ।\n১০. ওয়া মা আদরাকা মাহিয়াহ।\n১১. নারুন হামিয়াহ।",
            translationBangla = "১. মহাপ্রলয়!\n২. মহাপ্রলয় কী?\n৩. আপনি কি জানেন মহাপ্রলয় কী?\n৪. সেদিন মানুষ হবে বিক্ষিপ্ত পতঙ্গের ন্যায়,\n৫. এবং পাহাড়সমূহ হবে ধুনিত রঙিন পশমের মতো।\n৬. অতএব যার নেক আমলের পাল্লা ভারী হবে,\n৭. সে থাকবে পরম তৃপ্তিময় শান্তিতে।\n৮. পক্ষান্তরে যার পাল্লা হালকা হবে,\n৯. তার ঠিকানা হবে অতল হাবিয়া।\n১০. আর আপনি কি জানেন তা কী?\n১১. তা এক জ্বলন্ত অগ্নিকুণ্ড!"),
        QuranSurah(102, "التكاثر", "আত-তাকাসুর", "At-Takathur", "প্রাচুর্যের প্রতিযোগিতা", 8, "মাক্কী", "পারা ৩০",
            arabicText = "أَلْهَاكُمُ التَّكَاثُرُ ۝ حَتَّىٰ زُرْتُمُ الْمَقَابِرَ ۝ كَلَّا سَوْفَ تَعْلَمُونَ ۝ ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ ۝ كَلَّا لَوْ تَعْلَمُونَ عِلْمَ الْيَقِينِ ۝ لَتَرَوُنَّ الْجَحِيمَ ۝ ثُمَّ لَتَرَوُنَّهَا عَيْنَ الْيَقِينِ ۝ ثُمَّ لَتُسْأَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ ۝",
            transliterationBangla = "১. আলহাকুমুত তাকাছুর।\n২. হাত্তা যুরতুমুল মাক্বাবির।\n৩. কাল্লা সাওফা তা'লামূন।\n৪. ছুম্মা কাল্লা সাওফা তা'লামূন।\n৫. কাল্লা লাও তা'লামূনা 'ইলমাল ইয়াক্বীন।\n৬. লাতারাউন্নাল জাহীম।\n৭. ছুম্মা লাতারাউন্নাহা 'আইনাল ইয়াক্বীন।\n৮. ছুম্মা লাতুস'আলুন্না ইয়াওমাইযিন 'আনিন না'ঈম।",
            translationBangla = "১. প্রাচুর্যের প্রতিযোগিতা তোমাদের উদাসীন করে রেখেছে,\n২. যতক্ষণ না তোমরা কবরসমূহে উপনীত হও।\n৩. কখনো নয়, শীঘ্রই তোমরা জানতে পারবে!\n৪. পুনরায় বলি, কখনো নয়, শীঘ্রই তোমরা জানতে পারবে!\n৫. না, যদি তোমরা নিশ্চিত জ্ঞানে জানতে!\n৬. তোমরা অবশ্যই জাহান্নাম দেখতে পাবে।\n৭. অতঃপর তোমরা তা অবশ্যই চাক্ষুষ প্রত্যয়ে দেখতে পাবে।\n৮. এরপর সেদিন তোমাদেরকে অবশ্যই জীবনের সকল নিয়ামত সম্পর্কে জিজ্ঞাসা করা হবে।"),
        QuranSurah(103, "العصر", "আল-আসর", "Al-'Asr", "মহাকাল বা অপরাহ্ন", 3, "মাক্কী", "পারা ৩০",
            arabicText = "وَالْعَصْرِ ۝ إِنَّ الْإِنسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ ۝",
            transliterationBangla = "১. ওয়াল 'আসর।\n২. ইন্নাল ইনসানা লাফী খুসর।\n৩. ইল্লাল্লাযীনা আমানূ ওয়া 'আমিলুস সালিহাতি ওয়া তাওয়াসাও বিল-হাক্বক্বি ওয়া তাওয়াসাও বিস-সাবর।",
            translationBangla = "১. সময়ের শপথ!\n২. নিশ্চয় সমস্ত মানুষ মহা ক্ষতির মধ্যে নিমজ্জিত,\n৩. তারা ব্যতীত যারা ঈমান এনেছে, সৎকাজ করেছে এবং পরস্পরকে সত্যের উপদেশ দিয়েছে ও ধৈর্যের উপদেশ দিয়েছে।"),
        QuranSurah(104, "الهمزة", "আল-হুমাযাহ", "Al-Humazah", "পরনিন্দুক", 9, "মাক্কী", "পারা ৩০",
            arabicText = "وَيْلٌ لِّكُلِّ هُمَزَةٍ لُّمَزَةٍ ۝ الَّذِي جَمَعَ مَالًا وَعَدَّدَهُ ۝ يَحْسَبُ أَنَّ مَالَهُ أَخْلَدَهُ ۝ كَلَّا ۖ لَيُنبَذَنَّ فِي الْحُطَمَةِ ۝ وَمَا أَدْرَاكَ مَا الْحُطَمَةُ ۝ نَارُ اللَّهِ الْمُوقَدَةُ ۝ الَّتِي تَطَّلِعُ عَلَى الْأَفْئِدَةِ ۝ إِنَّهَا عَلَيْهِم مُّؤْصَدَةٌ ۝ فِي عَمَدٍ مُّمَدَّدَةٍ ۝",
            transliterationBangla = "১. ওয়াইলুল লিকুল্লি হুমাযাতিল লুমাযাহ।\n২. আল্লাযী জামা'আ মালাওঁ ওয়া 'আদ্দাদাহ।\n৩. ইয়াহসাবু আন্না মালাহূ আখলাদাহ।\n৪. কাল্লা লায়ুমবাযান্না ফিল হুতামাহ।\n৫. ওয়া মা আদরাকা মাল হুতামাহ।\n৬. নারুল্লাহিল মূক্বদাহ।\n৭. আল্লাতী তাত্তালি'উ আলাল আফ'ইদাহ।\n৮. ইন্নাহা আলাইহিম মু'সাদাহ।\n৯. ফী 'আমাদিম মুমাদ্দাদাহ।",
            translationBangla = "১. চরম দুর্ভোগ প্রত্যেক এমন ব্যক্তির যে সামনাসামনি গিবত করে ও পেছনে দোষ খোঁজে,\n২. যে অর্থ জমায় ও তা বারবার গণনা করে,\n৩. সে মনে করে তার সম্পদ তাকে অমর করে রাখবে।\n৪. কক্ষনো নয়! সে অবশ্যই হুতামায় নিক্ষিপ্ত হবে।\n৫. আর হুতামা কী, তা কি আপনি জানেন?\n৬. তা আল্লাহর প্রজ্জ্বলিত অগ্নি,\n৭. যা কলিজা পর্যন্ত পৌঁছে গ্রাস করে নেবে।\n৮. নিশ্চয় তা তাদেরকে আবদ্ধ করে রাখবে,\n৯. সুবিস্তৃত থামসমূহের ভেতর।"),
        QuranSurah(105, "الفيل", "আল-ফিল", "Al-Fil", "হাতি", 5, "মাক্কী", "পারা ৩০",
            arabicText = "أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَابِ الْفِيلِ ۝ أَلَمْ يَجْعَلْ كَيْدَهُمْ فِي تَضْلِيلٍ ۝ وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ ۝ تَرْمِيهِم بِحِجَارَةٍ مِّن سِجِّيلٍ ۝ فَجَعَلَهُمْ كَعَصْفٍ مَّأْكُولٍ ۝",
            transliterationBangla = "১. আলাম তারা কাইফা ফা'আলা রাব্বুকা বি-আসহাবিল ফিল।\n২. আলাম ইয়াজ'আল কাইদাহুম ফী তাদলীল।\n৩. ওয়া আরসালা আলাইহিম তাইরান আবাবীল।\n৪. তারমীহিম বিহিজারাতিম মিন সিজ্জীল।\n৫. ফাজা'আলাহুম কা'আসফিম মা'কূল।",
            translationBangla = "১. আপনি কি দেখেননি আপনার প্রতিপালক হাতিওয়ালাদের সাথে কেমন আচরণ করেছিলেন?\n২. তিনি কি তাদের চক্রান্ত ব্যর্থ করে দেননি?\n৩. এবং তাদের ওপর পাঠিয়েছিলেন ঝাঁকে ঝাঁকে আবাবিল পাখি,\n৪. যারা তাদের ওপর পোড়ামাটির পাথর বর্ষণ করেছিল,\n৫. অতঃপর তিনি তাদেরকে চর্বিত তৃণের ন্যায় চূর্ণবিচূর্ণ করে দিলেন।"),
        QuranSurah(106, "قريش", "কুরাইশ", "Quraysh", "কুরাইশ গোত্র", 4, "মাক্কী", "পারা ৩০",
            arabicText = "لِإِيلَافِ قُرَيْشٍ ۝ إِيلَافِهِمْ رِحْلَةَ الشِّتَاءِ وَالصَّيْفِ ۝ فَلْيَعْبُدُوا رَبَّ هَٰذَا الْبَيْتِ ۝ الَّذِي أَطْعَمَهُم مِّن جُوعٍ وَآمَنَهُم مِّنْ خَوْفٍ ۝",
            transliterationBangla = "১. লি-ঈলাফি কুরাইশ।\n২. ঈলাফিহিম রিহলাতাশ শিতা-ই ওয়াস সাইফ।\n৩. ফালইয়া'বুদূ রাব্বা হাযাল বাইত।\n৪. আল্লাযী আত'আমাহুম মিন জু'ইওঁ ওয়া আমানাহুম মিন খাওফ।",
            translationBangla = "১. কুরাইশদের আসক্তির কারণে,\n২. তাদের আসক্তি শীত ও গ্রীষ্মকালের বাণিজ্যিক ভ্রমণের,\n৩. অতএব তারা যেন এই ঘরের (পবিত্র কাবার) রবের ইবাদত করে,\n৪. যিনি তাদেরকে ক্ষুধায় অন্ন দিয়েছেন এবং ভয়-ভীতি থেকে নিরাপত্তা দান করেছেন।"),
        QuranSurah(107, "الماعون", "আল-মাউন", "Al-Ma'un", "গৃহস্থালির নিত্যপ্রয়োজনীয় বস্তু", 7, "মাক্কী", "পারা ৩০",
            arabicText = "أَرَأَيْتَ الَّذِي يُكَذِّبُ بِالدِّينِ ۝ فَذَٰلِكَ الَّذِي يَدُعُّ الْيَتِيمَ ۝ وَلَا يَحُضُّ عَلَىٰ طَعَامِ الْمِسْكِينِ ۝ فَوَيْلٌ لِّلْمُصَلِّينَ ۝ الَّذِينَ هُمْ عَن صَلَاتِهِمْ سَاهُونَ ۝ الَّذِينَ هُمْ يُرَاءُونَ ۝ وَيَمْنَعُونَ الْمَاعُونَ ۝",
            transliterationBangla = "১. আরাআইতাল্লাযী ইউকাযযিবু বিদ্দীন।\n২. ফাযালিকাল্লাযী ইয়াদু'উল ইয়াতীম।\n৩. ওয়ালা ইয়াহুদ্দু আলা ত্বা'আমিল মিসকীন।\n৪. ফাওয়াইলুল লিল-মুসাল্লীন।\n৫. আল্লাযীনা হুম 'আন সালাতিহিম সাহূন।\n৬. আল্লাযীনা হুম ইউরা-ঊন।\n৭. ওয়া ইয়ামনা'ঊনাল মা'ঊন।",
            translationBangla = "১. আপনি কি দেখেছেন তাকে, যে কর্মফল দিবসকে অস্বীকার করে?\n২. সে তো সেই ব্যক্তি, যে এতিমকে রুক্ষভাবে তাড়িয়ে দেয়,\n৩. এবং মিসকীনকে অন্নদানে উৎসাহিত করে না।\n৪. অতএব দুর্ভোগ সেই মুসল্লিদের জন্য,\n৫. যারা তাদের সালাত সম্পর্কে উদাসীন,\n৬. যারা লোক দেখানোর জন্য সালাত আদায় করে,\n৭. এবং নিত্যপ্রয়োজনীয় গৃহস্থালি সাহায্য প্রদানে বিরত থাকে।"),
        QuranSurah(108, "الكوثر", "আল-কাউসার", "Al-Kawthar", "প্রচুর কল্যাণ / হাউজে কাউসার", 3, "মাক্কী", "পারা ৩০",
            arabicText = "إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ ۝ إِنَّ شَانِئَكَ هُوَ الْأَبْتَرُ ۝",
            transliterationBangla = "১. ইন্না-আ'তাইকাল কাওসার।\n২. ফাসাল্লি লিরাব্বিকা ওয়ানহার।\n৩. ইন্না শানিআকা হুওয়াল আবতার।",
            translationBangla = "১. নিশ্চয়ই আমি আপনাকে কাউসার (অসীম কল্যাণ) দান করেছি।\n২. অতএব আপনার প্রতিপালকের উদ্দেশ্যে সালাত আদায় করুন এবং কোরবানি করুন।\n৩. নিশ্চয়ই আপনার শত্রুই নির্বংশ ও লেজকাটা।"),
        QuranSurah(109, "الكافرون", "আল-কাফিরুন", "Al-Kafirun", "অবিশ্বাসী কাফেরগণ", 6, "মাক্কী", "পারা ৩০",
            arabicText = "قُلْ يَا أَيُّهَا الْكَافِرُونَ ۝ لَا أَعْبُدُ مَا تَعْبُدُونَ ۝ وَلَا أَنتُمْ عَابِدُونَ مَا أَعْبُدُ ۝ وَلَا أَنَا عَابِدٌ مَّا عَبَدتُّمْ ۝ وَلَا أَنتُمْ عَابِدُونَ مَا أَعْبُدُ ۝ لَكُمْ دِينُكُمْ وَلِيَ دِينِ ۝",
            transliterationBangla = "১. ক্বুল ইয়া-আইয়্যুহাল কাফিরূন।\n২. লা-আ'বুদু মা তা'বুদূন।\n৩. ওয়া লা-আনতুম আবিদূনা মা আ'বুদ।\n৪. ওয়া লা-আনা আবিদুম মা আবাদতুম।\n৫. ওয়া লা-আনতুম আবিদূনা মা আ'বুদ।\n৬. লাকুম দীনুকুম ওয়ালিয়া দীন।",
            translationBangla = "১. বলুন: হে কাফের সম্প্রদায়!\n২. আমি তাদের উপাসনা করি না যাদের উপাসনা তোমরা করো,\n৩. এবং তোমরাও তাঁর উপাসক নও যাঁর উপাসনা আমি করি,\n৪. আর আমি তাঁদের পূজক নই যাদের পূজা তোমরা করে আসছ,\n৫. এবং তোমরাও তাঁর উপাসক নও যাঁর উপাসনা আমি করি।\n৬. তোমাদের জন্য তোমাদের দ্বীন এবং আমার জন্য আমার দ্বীন।"),
        QuranSurah(110, "النصر", "আন-নাসর", "An-Nasr", "আল্লাহর সাহায্য ও বিজয়", 3, "মাদানী", "পারা ৩০",
