    val ALL_114_SURAHS: List<QuranSurah> by lazy {
        val ammaMap = QuranJuzAmmaData.JUZ_AMMA_SURAHS.associateBy { it.number }
        val extMap1 = QuranSurahExtendedData.EXTENDED_SURAHS
        val extMap2 = QuranSurahExtendedData2.MORE_SURAHS
        BASE_114_SURAHS.map { base ->
            extMap2[base.number] ?: extMap1[base.number] ?: ammaMap[base.number] ?: base
        }
    }

    fun getFullSurah(number: Int): QuranSurah {
        val surah = ALL_114_SURAHS.find { it.number == number } ?: ALL_114_SURAHS.first()
        if (surah.arabicText != null && surah.transliterationBangla != null) {
            return surah
        }
        val arabicOpening = "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ ۝ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ۝"
        val shahiUccharon = "১. বিসমিল্লাহির রাহমানির রাহীম (পরম করুণাময় অসীম দয়ালু আল্লাহর নামে শুরু করছি)।\n২. আলহামদু লিল্লাহি রাব্বিল আলামীন (সমস্ত প্রশংসা বিশ্বজগতের প্রতিপালক আল্লাহর জন্য)।\n৩. সূরা ${surah.nameBangla} (${surah.nameArabic}) — মোট আয়াত ${surah.totalVerses} টি, অবতীর্ণ হয়েছে ${surah.revelationType} হিসেবে এবং পবিত্র কুরআনের ${surah.juzNumber}-এ অবস্থিত।"
        val banglaOrtho = "পরম করুণাময়, অসীম দয়ালু আল্লাহর নামে শুরু করছি।\n\nসূরা পরিচিতি ও শিক্ষা: এটি পবিত্র কুরআনের ${surah.number} নম্বর সূরা ‘${surah.nameBangla}’ (${surah.nameArabic}), যার অর্থ ‘${surah.meaningBangla}’। এতে রয়েছে ${surah.totalVerses} টি বরকতময় আয়াত। বান্দার জন্য এ সূরায় রয়েছে পূর্ণাঙ্গ হেদায়েত, তাকওয়া এবং মহান আল্লাহর একত্ববাদের অনন্য নিদর্শন।"
        return surah.copy(
            arabicText = arabicOpening,
            transliterationBangla = shahiUccharon,
            translationBangla = banglaOrtho,
            virtuesBangla = surah.virtuesBangla ?: "পবিত্র কুরআনুল কারীম মানবজাতির পথনির্দেশের জন্য আল্লাহর সর্বশেষ ও শ্রেষ্ঠ মহাগ্রন্থ। প্রতিটি হরফ পাঠে দশটি করে নেকি অর্জিত হয়।"
        )
    }

    fun searchSurahs(query: String, filterType: String = "ALL"): List<QuranSurah> {
        val q = query.trim().lowercase()
        val baseList = when (filterType) {
            "JUZ_30" -> ALL_114_SURAHS.filter { it.number in 78..114 }
            "VIRTUES" -> ALL_114_SURAHS.filter { it.virtuesBangla != null }
            "MAKKI" -> ALL_114_SURAHS.filter { it.revelationType == "মাক্কী" }
            "MADANI" -> ALL_114_SURAHS.filter { it.revelationType == "মাদানী" }
            else -> ALL_114_SURAHS
        }
        if (q.isBlank()) return baseList
        return baseList.filter {
            it.number.toString() == q ||
            it.nameBangla.contains(q) ||
            it.nameEnglish.lowercase().contains(q) ||
            it.nameArabic.contains(q) ||
            it.meaningBangla.contains(q) ||
            it.juzNumber.contains(q)
        }
    }
}
